html.strategy_js:
const proofSteps = [
  "Here is a cylinder with radius r and height h. Imagine it is a can with a paper label.",
  "Cut the label along the seam, straight down the side, and unroll it. The curved surface flattens into a rectangle.",
  "The rectangle is h tall. Its length is the distance once round the circular end, which is the circumference, 2πr.",
  "So the curved surface area is length × height = 2πr × h = 2πrh.",
  "A closed cylinder also has two circular ends, each πr². Total surface area = 2πr² + 2πrh."
];
let proofCurrentStep = 1;
function proofShowStep(n) {
  proofCurrentStep = Math.max(1, Math.min(5, n));
  document.querySelectorAll('.proof-layer').forEach(g => {
    g.classList.toggle('visible', parseInt(g.dataset.step, 10) <= proofCurrentStep);
  });
  document.getElementById('proofStepNum').textContent = proofCurrentStep;
  document.getElementById('proofStepText').textContent = proofSteps[proofCurrentStep - 1];
  document.getElementById('proofProgress').textContent = 'Step ' + proofCurrentStep + ' / 5';
  document.getElementById('proofPrev').disabled = (proofCurrentStep === 1);
  document.getElementById('proofNext').disabled = (proofCurrentStep === 5);
}
function proofNext() { proofShowStep(proofCurrentStep + 1); }
function proofPrev() { proofShowStep(proofCurrentStep - 1); }
function proofRestart() { proofShowStep(1); }
proofShowStep(1);
